def gen(n):
    for i in range(1, n+1):
        yield i

n = int(input())
for x in gen(n):
    print(x, end=' ')

def even_gen(n):
    for i in range(2, n+1, 2):
        yield i

n = int(input())
for x in even_gen(n):
    print(x, end=' ')

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a+b

n = int(input())
for x in fib(n):
    print(x, end=' ')

def infinite():
    i = 1
    while True:
        yield i
        i += 1

n = int(input())
g = infinite()
for _ in range(n):
    print(next(g), end=' ')

def gen(n):
    for i in range(1, n+1):
        yield i

def even_filter(seq):
    for x in seq:
        if x % 2 == 0:
            yield x

n = int(input())
for x in even_filter(gen(n)):
    print(x, end=' ')

def my_decorator(func):
    def wrapper():
        print('Start', end=' ')
        func()
        print('End')
    return wrapper

@my_decorator
def say():
    print('Hello', end=' ')

say()

def deco(func):
    def wrapper(x):
        return f"Result: {func(x)}"
    return wrapper

@deco
def square(x):
    return x * x

n = int(input())
print(square(n))

import time

def timer(func):
    def wrapper():
        start = time.time()
        func()
        end = time.time()
        print('Time:', round(end-start, 5))
    return wrapper

@timer
def run():
    for _ in range(1000000):
        pass

run()

def auth(func):
    def wrapper(flag):
        if flag:
            return func(flag)
        return 'Access Denied'
    return wrapper

@auth
def dashboard(flag):
    return 'Access Granted'

val = input() == 'True'
print(dashboard(val))

def log(func):
    def wrapper():
        print('Calling function', func.__name__)
        func()
    return wrapper

@log
def hello():
    pass

hello()

def deco(func):
    def wrapper(*args):
        return func(*args)
    return wrapper

@deco
def add(a, b):
    return f"Sum: {a+b}"

@deco
def mul(a, b):
    return f"Product: {a*b}"

print(add(2,3), mul(2,3))

def retry(func):
    def wrapper():
        for _ in range(3):
            try:
                return func()
            except:
                continue
        return 'Failed'
    return wrapper

@retry
def test():
    raise Exception

print(test())

class MyContext:
    def __enter__(self):
        print('Entered')
    def __exit__(self, exc_type, exc, tb):
        print('Exited')

with MyContext():
    pass

class Resource:
    def __enter__(self):
        print('Open')
        return self
    def __exit__(self, exc_type, exc, tb):
        print('Close')

with Resource() as r:
    print('Using')

class Safe:
    def __enter__(self):
        return self
    def __exit__(self, exc_type, exc, tb):
        if exc_type:
            print('Handled Error')
            return True

with Safe():
    raise ValueError

